// ❌ OLD: Each call to attach() adds a NEW listener to the shared
// emitter, capturing the closure (including any state in its scope).
// If attach() is called per request or per tick, the listener array
// grows forever, and every retained listener keeps its closure (and
// captured data) alive. The emitter (a long-lived root) pins all of
// it — a classic, silent memory leak.
const emitter = new EventEmitter();

function attach() {
  emitter.on('data', (chunk) => {
    processChunk(chunk); // ❌ OLD: closure retained forever
  });
}

// Called repeatedly:
for (let i = 0; i < 1_000_000; i++) attach();
// -> 1,000,000 listeners; Node warns MaxListenersExceeded after 10.

const { EventEmitter } = require('node:events');
const emitter = new EventEmitter();

function processChunk(c) {}

// ✅ NEW: once() removes the listener automatically after the first
// emission — the listener can never accumulate.
function attachOnce() {
  emitter.once('data', (chunk) => processChunk(chunk)); // ✅ NEW
}

// ✅ NEW: for repeated events, keep a reference and remove it when the
// owner is done (e.g. in a component/stream teardown):
function attachManaged() {
  const handler = (chunk) => processChunk(chunk);
  emitter.on('data', handler);
  // ... later, in cleanup:
  emitter.off('data', handler); // ✅ NEW: explicit removal
}

// ✅ NEW: cap the emitter to surface regressions early:
// emitter.setMaxListeners(100);
// Node warns at 10 by default — treat the warning as a leak signal.
